            <span style={{ color: trendColor, fontSize: '0.75rem', fontWeight: 600 }}>
              {trend > 0 ? `+${trend}%` : trend < 0 ? `${trend}%` : 'Stable'}
            </span>
          )}
        </div>
      )}
    </div>
  );
}

