      { type: 'RUBBER_TIRED_GANTRY', cap: 20, status: 'MAINTENANCE', berth: null, util: 0 },
    ],
  };

  const defs = craneDefs[tc];
  defs.forEach((d, i) => {
    const berthDoc = d.berth !== null ? berthDocs[d.berth] : null;
    cranes.push({
      craneId: `C${i + 1}-${tc}`,
      terminalId: tid,
      terminalCode: tc,
      berthId: berthDoc ? berthDoc._id : null,
      name: `${tc} Crane ${i + 1}`,
      type: d.type,
      status: d.status,
