'use strict';
const path = require('path');
require('dotenv').config({ path: path.resolve(__dirname, '../../../.env') });
const mongoose = require('mongoose');
const Vessel = require('../models/Vessel');
const Berth = require('../models/Berth');
const Crane = require('../models/Crane');
const Schedule = require('../models/Schedule');
const Alert = require('../models/Alert');
const CongestionPrediction = require('../models/CongestionPrediction');
const Recommendation = require('../models/Recommendation');
const HistoricalOperation = require('../models/HistoricalOperation');
const OperationsPlan = require('../models/OperationsPlan');
const Terminal = require('../models/Terminal');

const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/portmind';

async function verify() {
  await mongoose.connect(MONGODB_URI);
  console.log('\n=== Phase 3 Data Verification ===\n');

  // Collection counts
  const counts = {
    terminals: await Terminal.countDocuments(),
    berths: await Berth.countDocuments(),
    cranes: await Crane.countDocuments(),
    vessels: await Vessel.countDocuments(),
    schedules: await Schedule.countDocuments(),
    historicalOps: await HistoricalOperation.countDocuments(),
    predictions: await CongestionPrediction.countDocuments(),
    recommendations: await Recommendation.countDocuments(),
    alerts: await Alert.countDocuments(),
    plans: await OperationsPlan.countDocuments(),
  };
  console.log('Collection counts:');
  Object.entries(counts).forEach(([k, v]) => console.log(`  ${k.padEnd(20)}: ${v}`));

  // Reference checks
  console.log('\nReference integrity:');
  const atBerth = await Vessel.find({ status: 'AT_BERTH' });
  const atBerthWithRef = atBerth.filter(v => v.assignedBerthId);
  console.log(`  AT_BERTH vessels          : ${atBerth.length} / ${atBerthWithRef.length} have berthId`);

  const occupiedBerths = await Berth.find({ currentStatus: 'OCCUPIED' });
  const occupiedWithVessel = occupiedBerths.filter(b => b.assignedVesselId);
  console.log(`  OCCUPIED berths           : ${occupiedBerths.length} / ${occupiedWithVessel.length} have vesselId`);

  const assignedCranes = await Crane.find({ assignedVesselId: { $ne: null } });
  console.log(`  Cranes assigned to vessel : ${assignedCranes.length}`);

  const schedWithVessel = await Schedule.countDocuments({ vesselId: { $ne: null } });
  console.log(`  Schedules with vesselId   : ${schedWithVessel} / ${counts.schedules}`);

  // Vessel risk distribution
  console.log('\nVessel risk distribution:');
  const risks = await Vessel.aggregate([{ $group: { _id: '$congestionRisk', count: { $sum: 1 } } }, { $sort: { _id: 1 } }]);
  risks.forEach(r => console.log(`  ${(r._id || 'null').padEnd(10)}: ${r.count}`));

  // Congestion predictions by terminal
  console.log('\nCongestion predictions by terminal:');
  const preds = await CongestionPrediction.aggregate([{ $group: { _id: '$terminalCode', count: { $sum: 1 }, maxRisk: { $max: '$riskLevel' } } }]);
  preds.forEach(p => console.log(`  ${p._id}: ${p.count} predictions`));

  // Alert severity distribution
  console.log('\nAlert severity:');
  const alerts = await Alert.aggregate([{ $group: { _id: '$severity', count: { $sum: 1 } } }, { $sort: { _id: 1 } }]);
  alerts.forEach(a => console.log(`  ${(a._id).padEnd(10)}: ${a.count}`));

  // Vessel status distribution
  console.log('\nVessel status distribution:');
  const statuses = await Vessel.aggregate([{ $group: { _id: '$status', count: { $sum: 1 } } }, { $sort: { _id: 1 } }]);
  statuses.forEach(s => console.log(`  ${(s._id).padEnd(12)}: ${s.count}`));

  // Historical operations: verify 90 days per terminal
  console.log('\nHistorical operations by terminal:');
  const hist = await HistoricalOperation.aggregate([{ $group: { _id: '$terminalCode', count: { $sum: 1 }, avgBerthUtil: { $avg: '$avgBerthUtilizationPercent' } } }]);
  hist.forEach(h => console.log(`  ${h._id}: ${h.count} days, avg berth util ${Math.round(h.avgBerthUtil)}%`));

  console.log('\n=== Verification Complete ===\n');
  await mongoose.disconnect();
  process.exit(0);
}

verify().catch(err => { console.error('Verification failed:', err.message); process.exit(1); });

