  return Schedule.find({ vesselCode: vesselId })
    .sort({ plannedArrival: -1 })
    .populate('terminalId', 'terminalId name')
    .populate('berthId', 'berthId name')
    .lean();
}

module.exports = { listSchedules, getScheduleById, getSchedulesByVessel };

