.page {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  height: calc(100vh - var(--topnav-height) - 2 * var(--spacing-lg));
}

.filterBar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--border-radius-lg);
  padding: 12px 16px;
}

.searchWrap {
  position: relative;
  flex: 1;
  min-width: 200px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  pointer-events: none;
}

.searchInput {
  padding-left: 32px;
  padding-right: 28px;
}

.clearSearch {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-muted);
  padding: 0;
  display: flex;
}

.filterSelect {
  width: 140px;
  flex-shrink: 0;
}

.count {
  margin-left: auto;
  font-size: 0.75rem;
  color: var(--text-muted);
  white-space: nowrap;
}

.content {
  display: flex;
  flex: 1;
  gap: var(--spacing-md);
  overflow: hidden;
}

.tableWrap {
  flex: 1;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.tableWrapNarrow {
  flex: 1;
  min-width: 0;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.tableScroll {
  flex: 1;
  overflow: auto;
}

.sortable {
  cursor: pointer;
  user-select: none;
}
.sortable:hover {
  color: var(--accent);
}

.row {
  cursor: pointer;
}

.rowSelected {
  background: var(--accent-dim) !important;
}

.vesselName {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 500;
}

.vesselSub {
  font-size: 0.72rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.mono {
  font-variant-numeric: tabular-nums;
  font-size: 0.8rem;
}

.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 12px;
  border-top: 1px solid var(--border);
}

.pageInfo {
  font-size: 0.8rem;
  color: var(--text-muted);
}

@media (max-width: 900px) {
  .filterSelect {
    width: 120px;
  }
  .content {
    flex-direction: column;
  }
}

