          <DetailRow label="Type" value={vessel.vesselType} />
          <DetailRow label="Shipping Line" value={vessel.shippingLine} />
          <DetailRow label="Flag" value={vessel.flag} />
          <DetailRow label="Cargo Type" value={vessel.cargoType} />
