  flex-shrink: 0;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--border-radius-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.panelHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-secondary);
}

.panelTitle {
  display: flex;
  align-items: center;
  gap: 8px;
}

.panelTitle h3 {
  font-size: 0.9rem;
  font-weight: 600;
}

.panelBody {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.badges {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.highPriority {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--risk-high);
  background: var(--risk-high-bg);
  border: 1px solid var(--risk-high);
  padding: 2px 6px;
  border-radius: 4px;
}

.section {
  border-top: 1px solid var(--border);
  padding-top: 10px;
}

.sectionTitle {
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 6px;
}

.detailRow {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  padding: 3px 0;
  font-size: 0.8rem;
}

.detailLabel {
  color: var(--text-muted);
  flex-shrink: 0;
  width: 110px;
}

.detailValue {
  color: var(--text-primary);
  text-align: right;
  word-break: break-all;
}

.mono {
  font-variant-numeric: tabular-nums;
}

.craneRow {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 0;
  font-size: 0.8rem;
  color: var(--text-secondary);
}

.craneType {
  font-size: 0.7rem;
  color: var(--text-muted);
  margin-left: auto;
}

.riskScore {
  display: flex;
  align-items: center;
  gap: 12px;
}

.scoreNum {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.scheduleItem {
  padding: 6px 0;
  border-bottom: 1px solid var(--border);
}

.scheduleId {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.scheduleMeta {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.scheduleDetail {
  font-size: 0.75rem;
  color: var(--text-muted);
}

