.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
}

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-secondary);
}

.headerLeft {
  display: flex;
  align-items: center;
  gap: 10px;
}

.terminalName {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-primary);
}

.terminalId {
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-top: 2px;
}

.headerRight {
  display: flex;
  align-items: center;
  gap: 8px;
}

.kpiRow {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
}

.kpi {
  flex: 1;
  padding: 10px 14px;
  border-right: 1px solid var(--border);
}

.kpi:last-child {
  border-right: none;
}

.kpiLabel {
  display: block;
  font-size: 0.68rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.kpiValue {
  font-size: 0.82rem;
  color: var(--text-primary);
  font-weight: 500;
}

.utilSection {
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-bottom: 1px solid var(--border);
}

.utilWrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.utilLabel {
  font-size: 0.72rem;
  color: var(--text-muted);
  width: 110px;
  flex-shrink: 0;
}

.utilBarBg {
  flex: 1;
  height: 6px;
  background: var(--bg-secondary);
  border-radius: 3px;
  overflow: hidden;
}

.utilBarFill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.4s ease;
}

.utilValue {
  font-size: 0.78rem;
  font-weight: 700;
  width: 38px;
  text-align: right;
  flex-shrink: 0;
}

.expandBtn {
  width: 100%;
  padding: 9px 16px;
  background: transparent;
  border: none;
  border-top: 1px solid var(--border);
  cursor: pointer;
  color: var(--text-muted);
  font-size: 0.78rem;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: background 0.15s;
}

.expandBtn:hover {
  background: var(--bg-secondary);
  color: var(--text-primary);
}

.expandedSection {
  border-top: 1px solid var(--border);
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

